const IMAGE_URL = "https://example.com/welcome.png";

async function loadRecipients() {
  const raw = await fs.readFile(RECIPIENTS_PATH, "utf8");
  const parsed = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error("recipients.json must contain an array of email strings");
  }
  return parsed;
}

function buildPayload(email) {
  return {
    recipient: `email:${email}:polygon-amoy`,
    metadata: {
      name: "Welcome NFT",
      description: "Airdrop token",
      image: IMAGE_URL,
    },
  };
}

