        status: "error",
        response: error instanceof Error ? error.message : String(error),
      });
    }
  }

  const summary = {
    total: recipients.length,
    results,
  };

  await fs.writeFile(SUMMARY_PATH, JSON.stringify(summary, null, 2));
}

run().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
